      "https://learn.microsoft.com/en-us/power-platform/power-fx/reference/function-readnfc",
      "https://learn.microsoft.com/en-us/power-platform/power-fx/reference/function-recordinfo",
      "https://learn.microsoft.com/en-us/power-platform/power-fx/reference/function-trace",
