var keyFor = (issue3) => {
  const suffix = issue3.property ? `${issue3.type}.${issue3.property}` : issue3.type;
  if (issue3.level === "REFUSE") return `refuse:${issue3.rule ?? "unclassified-refusal"}:${suffix}`;
  if (issue3.rule === "unverified-augmentation") return `warn:${suffix}`;
  return issue3.rule ? `lint:${issue3.rule}:${suffix}` : `warn:${suffix}`;
};
var issueIncrements = (issues) => {
  const increments = /* @__PURE__ */ new Map();
  for (const issue3 of issues) {
    if (issue3.level !== "WARN" && issue3.level !== "REFUSE") continue;
    const key = keyFor(issue3);
    const current = increments.get(key) ?? { occurrences: 0 };
    current.occurrences++;
    if (issue3.level === "REFUSE" && typeof issue3.nearMiss === "boolean") {
      current.nearMiss = issue3.nearMiss;
    }
    increments.set(key, current);
  }
  return increments;
};
async function writeIssueRecords(kv, increments, now) {
  await Promise.allSettled([...increments].map(async ([key, increment]) => {
    const current = await kv.get(key, "json");
    const { near_miss: _previousNearMiss, ...preserved } = current ?? {};
    const next = {
      ...preserved,
      // count is runs affected: the per-run map guarantees exactly one bump.
      count: (current?.count ?? 0) + 1,
      // A v1 record used count as its raw counter; use that as the upgrade default.
      occurrences: (current?.occurrences ?? current?.count ?? 0) + increment.occurrences,
      // An upgraded v1 record is not genuinely new and has no trustworthy first_seen.
      ...current ? current.first_seen === void 0 ? {} : { first_seen: current.first_seen } : { first_seen: now },
      last_seen: now,
      worker_version: WORKER_VERSION,
      catalog_version: CATALOG_VERSION,
      ...increment.nearMiss === void 0 ? {} : { near_miss: increment.nearMiss }
    };
    await kv.put(key, JSON.stringify(next));
  }));
}
async function writeStats(kv, input, opportunities, now) {
  const current = await kv.get("stats:validate", "json");
  const cumulativeOpportunities = { ...current?.opportunities ?? {} };
  for (const [rule, amount] of Object.entries(opportunities)) {
    if (!Number.isFinite(amount) || amount <= 0) continue;
    cumulativeOpportunities[rule] = (cumulativeOpportunities[rule] ?? 0) + amount;
  }
  const warnIssues = input.issues.filter((issue3) => issue3.level === "WARN").length;
  const refuseIssues = input.issues.filter((issue3) => issue3.level === "REFUSE").length;
  const next = {
    runs: (current?.runs ?? 0) + 1,
    files: (current?.files ?? 0) + input.files,
    clear_runs: (current?.clear_runs ?? 0) + (warnIssues === 0 && refuseIssues === 0 ? 1 : 0),
    warn_runs: (current?.warn_runs ?? 0) + (warnIssues > 0 ? 1 : 0),
    refuse_runs: (current?.refuse_runs ?? 0) + (refuseIssues > 0 ? 1 : 0),
    warn_issues: (current?.warn_issues ?? 0) + warnIssues,
    refuse_issues: (current?.refuse_issues ?? 0) + refuseIssues,
    opportunities: cumulativeOpportunities,
    since: current?.since ?? now,
    last_seen: now,
    worker_version: WORKER_VERSION,
    catalog_version: CATALOG_VERSION
  };
  await kv.put("stats:validate", JSON.stringify(next));
}
function recordValidationTelemetry(env2, ctx2, input) {
  const kv = env2.VERIFICATION_QUEUE;
  if (!kv) return;
  ctx2.waitUntil((async () => {
    try {
      const now = (/* @__PURE__ */ new Date()).toISOString();
      const increments = issueIncrements(input.issues);
      const opportunities = input.opportunities?.() ?? {};
      await Promise.allSettled([
        writeIssueRecords(kv, increments, now),
        writeStats(kv, input, opportunities, now)
      ]);
    } catch {
    }
  })());
}
async function readValidationStats(env2) {
  const kv = env2.VERIFICATION_QUEUE;
  if (!kv) return null;
  const stats = await kv.get("stats:validate", "json");
  return stats ? { ...stats, opportunities: stats.opportunities ?? {} } : null;
}
var DEFAULT_QUEUE_PREFIXES = ["warn:", "lint:", "refuse:"];
async function readVerificationQueue(env2, opts = {}) {
  const kv = env2.VERIFICATION_QUEUE;
  if (!kv) return [];
  const limit = Math.max(1, Math.min(200, opts.limit ?? 50));
  const list = await kv.list({ prefix: opts.prefix, limit: 1e3 });
  const entries = await Promise.all(list.keys.filter((key) => opts.prefix !== void 0 || DEFAULT_QUEUE_PREFIXES.some((prefix) => key.name.startsWith(prefix))).map(async (key) => {
    const value = await kv.get(key.name, "json");
    if (!value || !opts.includeAdjudicated && value.adjudication) return null;
    const entry = {
      key: key.name,
      count: value.count ?? 0,
      occurrences: value.occurrences ?? value.count ?? 0,
      last_seen: value.last_seen ?? ""
    };
    if (value.first_seen !== void 0) entry.first_seen = value.first_seen;
    if (value.worker_version !== void 0) entry.worker_version = value.worker_version;
    if (value.catalog_version !== void 0) entry.catalog_version = value.catalog_version;
    if (value.near_miss !== void 0) entry.near_miss = value.near_miss;
    if (value.adjudication !== void 0) entry.adjudication = value.adjudication;
    return entry;
  }));
  return entries.filter((entry) => entry !== null).sort((a, b) => b.count - a.count || a.key.localeCompare(b.key)).slice(0, limit);
}

