// src/lib/markdown.ts
function listSections(content) {
  const out = [];
  for (const ln of content.split("\n")) {
    const m = ln.match(/^(#{1,6})\s+(.+?)\s*$/);
    if (m) out.push({ level: m[1].length, title: m[2] });
  }
  return out;
}
var norm = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "");
function extractSection(content, sectionTitle) {
  const target = norm(sectionTitle);
  const lines2 = content.split("\n");
  let startIdx = -1;
  let startLevel = 0;
  for (let i = 0; i < lines2.length; i++) {
    const m = lines2[i].match(/^(#{1,6})\s+(.+?)\s*$/);
    if (!m) continue;
    if (norm(m[2]).includes(target)) {
      startIdx = i;
      startLevel = m[1].length;
      break;
    }
  }
  if (startIdx === -1) return null;
  let endIdx = lines2.length;
  for (let j = startIdx + 1; j < lines2.length; j++) {
    const m = lines2[j].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= startLevel) {
      endIdx = j;
      break;
    }
  }
  return lines2.slice(startIdx, endIdx).join("\n").trim();
}
function searchParagraphs(content, needle, maxResults = 5) {
  const q = needle.toLowerCase();
  const paragraphs = content.split(/\n\s*\n/);
  const matches = [];
  for (const p of paragraphs) {
    if (p.toLowerCase().includes(q)) {
      matches.push(p.trim());
      if (matches.length >= maxResults) break;
    }
  }
  return matches;
}

